<script setup>
import ClientIndependenceReview from './ClientIndependenceReview.vue';
import {ref,watch} from 'vue';import api from '../../services/api';
const props=defineProps({clientId:Number,agencyId:Number});const data=ref(null),scopes=ref([]),reviewed=ref(false),error=ref(''),notice=ref(''),busy=ref(false);let generation=0;
async function load(){const run=++generation;data.value=null;try{const r=await api.get(`/dependent-portal/staff/${props.clientId}`,{params:{agencyId:props.agencyId},skipGlobalLoading:true});if(run===generation){data.value=r.data;scopes.value=r.data.scopes||[];reviewed.value=false;}}catch(e){if(run===generation&&e.response?.status!==403)error.value='Personal portal sharing could not load.';}}
async function save(restore=false){busy.value=true;error.value='';try{await api.put(`/dependent-portal/staff/${props.clientId}`,{agencyId:props.agencyId,scopes:scopes.value,reviewed:reviewed.value,restore});if(restore)data.value.active=true;notice.value='Personal portal sharing updated.';}catch(e){error.value=e.response?.data?.error?.message||'Could not save sharing.';}finally{busy.value=false;}}
watch(()=>[props.clientId,props.agencyId],load,{immediate:true});
</script>
<template><ClientIndependenceReview :client-id="clientId" /><section v-if="data?.invited" class="personal-sharing"><h3>Client’s personal portal</h3><p>{{data.email}} · {{data.active?'Active invitation':'Access turned off'}}</p><p>These choices apply only to this client’s separate login. Family access stays separate.</p><form @submit.prevent="save(false)"><label v-for="(label,key) in {treatment_plan:'Shared treatment plan',clinical_documents:'Individually shared documents'}" :key="key"><input v-model="scopes" type="checkbox" :value="key" />{{label}}</label><p>Documents still need to be shared with this recipient from the document’s sharing controls.</p><label><input v-model="reviewed" type="checkbox" required />I reviewed what is appropriate to share directly with this client.</label><button :disabled="busy||!reviewed">Save personal sharing</button><button v-if="!data.active" type="button" :disabled="busy||!reviewed" @click="save(true)">Restore personal access</button></form><p v-if="notice" role="status">{{notice}}</p><p v-if="error" role="alert">{{error}}</p></section></template>
<style scoped>.personal-sharing{padding:20px;border:1px solid #ccd9e5;border-radius:12px;margin-bottom:18px;background:#f6f9fc}.personal-sharing label{display:flex;gap:10px;margin:12px 0}.personal-sharing button{padding:10px 14px;font:inherit}[role=alert]{color:#a12222}</style>
